using Microsoft.EntityFrameworkCore; using MSA.Contracts; using MSA.EventBus.Abstractions; using MSA.EventBusOutbox; using MSA.InventoryService.Domain; using MSA.InventoryService.Infrastructure; using System.Text.Json;
namespace MSA.InventoryService.Integration;
internal sealed class OrderSubmittedHandler(InventoryDbContext db,IOutboxStore outbox):IIntegrationEventHandler<OrderSubmittedIntegrationEvent>
{
 public async Task HandleAsync(OrderSubmittedIntegrationEvent e,CancellationToken ct=default){await using var tx=await db.BeginTransactionAsync(ct);if(!await db.TryBeginMessageAsync(e.Id,nameof(OrderSubmittedHandler),ct)){await db.RollbackTransactionAsync(ct);return;}try{var skus=e.Items.Select(x=>x.Sku).ToArray();var stock=await db.StockItems.Where(x=>skus.Contains(x.Sku)).ToDictionaryAsync(x=>x.Sku,ct);if(e.Items.Any(x=>!stock.TryGetValue(x.Sku,out var s)||s.Available<x.Quantity)){Add(new InventoryRejectedIntegrationEvent{OrderId=e.OrderId,Reason="Insufficient inventory."});}else{foreach(var line in e.Items)stock[line.Sku].Reserve(line.Quantity);var reservation=new InventoryReservation(Guid.NewGuid(),e.OrderId,e.Items.Select(x=>new InventoryReservationLine(x.Sku,x.Quantity)));db.Reservations.Add(reservation);Add(new InventoryReservedIntegrationEvent{OrderId=e.OrderId,ReservationId=reservation.Id,Amount=e.Amount,Currency=e.Currency,PaymentMethod=e.PaymentMethod});}await db.CommitTransactionAsync(tx,ct);}catch{await db.RollbackTransactionAsync(ct);throw;}void Add(IntegrationEvent value)=>outbox.Add(OutboxMessage.Create(value.GetType().AssemblyQualifiedName!,JsonSerializer.Serialize(value,value.GetType())));}
}
internal sealed class ReleaseInventoryHandler(InventoryDbContext db,IOutboxStore outbox):IIntegrationEventHandler<ReleaseInventoryIntegrationEvent>
{
 public async Task HandleAsync(ReleaseInventoryIntegrationEvent e,CancellationToken ct=default){await using var tx=await db.BeginTransactionAsync(ct);if(!await db.TryBeginMessageAsync(e.Id,nameof(ReleaseInventoryHandler),ct)){await db.RollbackTransactionAsync(ct);return;}try{var reservation=await db.Reservations.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==e.ReservationId,ct);if(reservation is not null&&reservation.Status==ReservationStatus.Reserved){var skus=reservation.Lines.Select(x=>x.Sku).ToArray();var stock=await db.StockItems.Where(x=>skus.Contains(x.Sku)).ToDictionaryAsync(x=>x.Sku,ct);foreach(var line in reservation.Lines)stock[line.Sku].Release(line.Quantity);reservation.Release();var ev=new InventoryReleasedIntegrationEvent{OrderId=e.OrderId,ReservationId=e.ReservationId};outbox.Add(OutboxMessage.Create(ev.GetType().AssemblyQualifiedName!,JsonSerializer.Serialize(ev,ev.GetType())));}await db.CommitTransactionAsync(tx,ct);}catch{await db.RollbackTransactionAsync(ct);throw;}}
}
internal sealed class CommitInventoryHandler(InventoryDbContext db):IIntegrationEventHandler<CommitInventoryIntegrationEvent>
{
 public async Task HandleAsync(CommitInventoryIntegrationEvent e,CancellationToken ct=default){await using var tx=await db.BeginTransactionAsync(ct);if(!await db.TryBeginMessageAsync(e.Id,nameof(CommitInventoryHandler),ct)){await db.RollbackTransactionAsync(ct);return;}try{var reservation=await db.Reservations.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.Id==e.ReservationId,ct);if(reservation is not null&&reservation.Status==ReservationStatus.Reserved){var skus=reservation.Lines.Select(x=>x.Sku).ToArray();var stock=await db.StockItems.Where(x=>skus.Contains(x.Sku)).ToDictionaryAsync(x=>x.Sku,ct);foreach(var line in reservation.Lines)stock[line.Sku].Commit(line.Quantity);reservation.Commit();}await db.CommitTransactionAsync(tx,ct);}catch{await db.RollbackTransactionAsync(ct);throw;}}
}
